<?php
require dirname(__DIR__).'/app/bootstrap.php';
date_default_timezone_set(setting('timezone','Asia/Colombo'));
$page=resolveStoreRoute();if($page==='missing')http_response_code(404);
$cats=all('SELECT * FROM categories WHERE enabled=1 ORDER BY sort_order,name');$title=ucfirst($page).' · '.setting('store_name');$product=null;$problem=null;try{if(in_array($page,['login','register','forgot','reset'],true))module('accounts');if($page==='product'){$product=Catalog::product((int)($_GET['id']??0));$title=$product['seo_title']?:$product['name'].' · '.setting('store_name');q('UPDATE products SET views=views+1 WHERE id=?',[$product['id']]);}if($page==='order')$order=Commerce::detail((int)($_GET['id']??0),$_GET['token']??'');if($page==='account'&&!customer()){$page='login';}if($page==='wishlist')module('wishlist');}catch(AppError $ex){$problem=$ex->getMessage();http_response_code($ex->status);}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="csrf-token" content="<?=e(csrf())?>"><meta name="app-base" content="<?=e(base())?>"><meta name="currency-symbol" content="<?=e(setting('currency_symbol'))?>"><title><?=e($title)?></title><meta name="description" content="<?=e($product['seo_description']??setting('tagline'))?>"><?php if(in_array($page,['home','shop','product','policy','contact'],true)):?><link rel="canonical" href="<?=e(rtrim((string)setting('site_origin','http://localhost'),'/').url($page,$page==='shop'?array_diff_key($_GET,['id'=>1,'page'=>1]):($page==='product'?['id'=>$product['id']]:($page==='policy'?['slug'=>$_GET['slug']??'']:[]))))?>"><?php else:?><meta name="robots" content="noindex,follow"><?php endif?><link rel="stylesheet" href="<?=e(asset('assets/app.css'))?>"><link rel="stylesheet" href="<?=e(asset('assets/fashion.css'))?>"><script defer src="<?=e(asset('assets/app.js'))?>"></script></head><body data-page="<?=e($page)?>">
<div class="topbar"><div class="container between"><span><?=e(setting('top_message'))?></span><div><a href="<?=e(url('contact'))?>">Help & support</a><i></i><a href="<?=e(url('track'))?>">Track order</a><i></i><span><?=e(setting('currency'))?></span></div></div></div>
<header class="main-header container"><a class="logo" href="<?=e(url('home'))?>"><?php if(setting('logo')):?><img src="<?=e(base(setting('logo')))?>" alt="<?=e(setting('store_name'))?>"><?php else:?><span class="logo-mark"><?=View::icon('box')?></span><span><?=e(setting('store_name'))?><small><?=e(setting('tagline'))?></small></span><?php endif?></a><form class="search" action="<?=e(url('shop'))?>" role="search"><label class="sr-only" for="search-input">Search products</label><input id="search-input" name="q" placeholder="Search products, brands and more…" value="<?=e($_GET['q']??'')?>" autocomplete="off" aria-controls="suggestions"><button aria-label="Search"><?=View::icon('search')?></button><div id="suggestions" class="suggestions" hidden></div></form><div class="header-actions"><?php if(enabled('accounts')):?><a href="<?=e(url('account'))?>"><?=View::icon('user')?><span>My account<small><?=$_SESSION['customer_id']??false?'Welcome back':'Sign in'?></small></span></a><?php endif?><?php if(enabled('wishlist')):?><a href="<?=e(url('wishlist'))?>" aria-label="Wishlist"><?=View::icon('heart')?><span>Wishlist</span></a><?php endif?><a href="<?=e(url('cart'))?>" class="cart-link"><?=View::icon('cart')?><span>Cart</span><b data-cart-count><?=array_sum($_SESSION['cart']??[])?></b></a></div></header>
<nav class="nav-wrap" aria-label="Store navigation"><div class="container nav"><button class="category-toggle" aria-expanded="false" aria-controls="category-menu"><?=View::icon('menu')?> All categories</button><div id="category-menu" class="category-menu" hidden><?php foreach($cats as $c):?><a href="<?=e(url('shop',['category'=>$c['id']]))?>"><?=e(($c['parent_id']?'↳ ':'').$c['name'])?></a><?php endforeach?></div><div class="nav-links"><?php foreach(array_slice(array_filter($cats,fn($c)=>!$c['parent_id']),0,6) as $c):?><a href="<?=e(url('shop',['category'=>$c['id']]))?>"><?=e($c['name'])?></a><?php endforeach?></div><a class="accent" href="<?=e(url('shop',['deal'=>1]))?>">Sale</a><?php if(enabled('preorders')):?><a class="optional-nav" href="<?=e(url('shop',['preorder'=>1]))?>">Pre-orders</a><?php endif?><?php if(enabled('used')):?><a class="optional-nav" href="<?=e(url('shop',['condition'=>'used']))?>">Pre-loved</a><?php endif?></div></nav>
<main id="main"><?php if($problem):?><div class="container empty"><h1>Unable to open this page</h1><p><?=e($problem)?></p><a class="button" href="<?=e(url('home'))?>">Return to store</a></div><?php else:require ROOT.'/resources/views/store.php';endif?></main>
<footer><div class="container footer-grid"><div><a class="logo" href="<?=e(url('home'))?>"><?=e(setting('store_name'))?></a><p><?=e(setting('tagline'))?></p><p class="muted"><?=nl2br(e(setting('address')))?></p></div><div><h3>Explore</h3><a href="<?=e(url('shop'))?>">Shop all products</a><a href="<?=e(url('track'))?>">Order tracking</a><a href="<?=e(url('contact'))?>">Contact the store</a><a href="<?=e(base('admin/'))?>">Staff sign in</a></div><div><h3>Good to know</h3><?php foreach(all('SELECT slug,title FROM pages WHERE enabled=1') as $p):?><a href="<?=e(url('policy',['slug'=>$p['slug']]))?>"><?=e($p['title'])?></a><?php endforeach?></div><div><h3>Stay connected</h3><p><?=e(setting('email'))?><br><?=e(setting('phone'))?></p><?php foreach(setting('social_links',[]) as $name=>$link):?><a target="_blank" rel="noopener noreferrer" href="<?=e(safeLink($link))?>"><?=e($name)?></a><?php endforeach?></div></div><p class="container demo-notice"><?=e(setting('footer_text'))?></p><?php View::credit()?></footer><div id="toast" role="status" aria-live="polite" hidden></div><dialog id="image-zoom"><button class="icon-button" data-close-dialog aria-label="Close image"><?=View::icon('close')?></button><img alt="Enlarged product"></dialog></body></html>
